    function mint(address to, uint256 amount) external { _mint(to, amount); }
    function faults(bool b, bool t, bool f) external { failBalance=b; failTransfer=t; failTransferFrom=f; }
    function setCallback(address target, bytes calldata data) external { callbackTarget=target; callbackData=data; }
    function balanceOf(address account) public view override returns (uint256) { require(!failBalance,"balance fault"); return super.balanceOf(account); }
    function transfer(address to, uint256 value) public override returns (bool) {
        require(!failTransfer,"transfer fault"); _callback(); return super.transfer(to,value);
    }
    function transferFrom(address from, address to, uint256 value) public override returns (bool) {
        require(!failTransferFrom,"transferFrom fault"); _callback(); return super.transferFrom(from,to,value);
    }
    function _callback() internal {
        if(callbackTarget!=address(0)) { (bool ok,)=callbackTarget.call(callbackData); callbackRejected=!ok; }
    }
}

contract OrderRecorder {
    uint256 public clock;
    mapping(address=>uint256) public sequence;
    function record() external { sequence[msg.sender]=++clock; }
}

contract TestBoost {
    OrderRecorder public recorder;
    uint256 public delegated=12345;
    uint256 public checkpoints;
    bool public failRead;
    bool public failCheckpoint;
    constructor(address recorder_) { recorder=OrderRecorder(recorder_); }
    function faults(bool r,bool c) external { failRead=r; failCheckpoint=c; }
    function delegatedIn(address) external view returns(uint256) { require(!failRead,"boost read"); return delegated; }
    function checkpointUser(address) external { require(!failCheckpoint,"boost checkpoint"); checkpoints++; recorder.record(); }
}

contract TestGauge {
    address public staking_token;
    OrderRecorder public recorder;
    address[] private _rewards;
    mapping(address=>uint256) public balances;
    mapping(address=>mapping(address=>uint256)) public earned;
    bool public failDeposit;
    bool public failWithdraw;
    bool public failCheckpoint;
    bool public checkpointResult=true;
    uint256 public checkpoints;
    constructor(address asset,address order) { staking_token=asset; recorder=OrderRecorder(order); }
    function addReward(address token) external { _rewards.push(token); }
    function reward_tokens(uint256 i) external view returns(address) { return i<_rewards.length?_rewards[i]:address(0); }
    function reward(address user,address token,uint256 amount) external { TestToken(token).mint(address(this),amount); earned[user][token]+=amount; }
    function claimable_reward(address user,address token) external view returns(uint256) { return earned[user][token]; }
    function claim_rewards(address user,address receiver) external {
        for(uint256 i;i<_rewards.length;i++) { address token=_rewards[i]; uint256 a=earned[user][token]; earned[user][token]=0; if(a!=0)require(TestToken(token).transfer(receiver,a)); }
    }
    function faults(bool d,bool w,bool c,bool result) external { failDeposit=d; failWithdraw=w; failCheckpoint=c; checkpointResult=result; }
    function deposit(uint256 a,address user) external { require(!failDeposit,"gauge deposit"); require(TestToken(staking_token).transferFrom(msg.sender,address(this),a)); balances[user]+=a; }
    function withdraw(uint256 a,bool claimRewards) external { require(!failWithdraw,"gauge withdraw"); balances[msg.sender]-=a; require(TestToken(staking_token).transfer(msg.sender,a)); if(claimRewards) this.claim_rewards(msg.sender,msg.sender); }
    function user_checkpoint(address) external returns(bool) { require(!failCheckpoint,"gauge checkpoint"); checkpoints++; recorder.record(); return checkpointResult; }
    function alternateCheckpoint(address) external { require(!failCheckpoint,"gauge checkpoint"); checkpoints++; recorder.record(); }
}

contract TestDelegateRegistry {
    mapping(address=>mapping(bytes32=>address)) public delegates;
    function setDelegate(bytes32 space,address delegate) external { delegates[msg.sender][space]=delegate; }
}

contract TestStash {
    mapping(address=>bytes32) public merkleRoot;
    mapping(address=>uint256) public update;
    mapping(address=>mapping(uint256=>bool)) private _claimed;
    mapping(address=>bool) public failClaim;
    function publish(address token,bytes32 root,uint256 amount) external { merkleRoot[token]=root; update[token]++; TestToken(token).mint(address(this),amount); }
    function setFailure(address token,bool fail) external { failClaim[token]=fail; }
    function markClaimed(address token,uint256 index) external { _claimed[token][index]=true; }
    function isClaimed(address token,uint256 index) external view returns(bool) { return _claimed[token][index]; }
    function claim(address token,uint256 index,address account,uint256 amount,bytes32[] calldata proof) external {
        require(!failClaim[token]&&!_claimed[token][index],"stash claim");
        bytes32 h=keccak256(abi.encodePacked(index,account,amount));
        for(uint256 i;i<proof.length;i++) { h=h<=proof[i]?keccak256(abi.encodePacked(h,proof[i])):keccak256(abi.encodePacked(proof[i],h)); }
        require(h==merkleRoot[token],"proof"); _claimed[token][index]=true; require(TestToken(token).transfer(account,amount));
    }
}

